package main

import (
	"bytes"
	"encoding/json"
	"fmt"
	"sort"
	"strings"
	"text/tabwriter"
)

type Position struct {
	Filename string `json:"Filename"`
	Offset   int    `json:"Offset"`
	Line     int    `json:"Line"`
	Column   int    `json:"Column"`
}

type FailurePosition struct {
	Start Position `json:"Start"`
	End   Position `json:"End"`
}

type Failure struct {
	Severity        string          `json:"Severity"`
	Failure         string          `json:"Failure"`
	RuleName        string          `json:"RuleName"`
	Category        string          `json:"Category"`
	Position        FailurePosition `json:"Position"`
	Confidence      float64         `json:"Confidence"`
	ReplacementLine string          `json:"ReplacementLine"`
	// internal: raw severity for sarif level
	rawSeverity string `json:"-"`
}

func formatFailures(formatterName string, failures []Failure, enabledRules map[string]RuleConfig, globalSeverity string) (string, error) {
	switch formatterName {
	case "", "default":
		return formatDefault(failures), nil
	case "plain":
		return formatPlain(failures), nil
	case "unix":
		return formatUnix(failures), nil
	case "json":
		return formatJSON(failures), nil
	case "ndjson":
		return formatNDJSON(failures), nil
	case "friendly":
		return formatFriendly(failures), nil
	case "stylish":
		return formatStylish(failures), nil
	case "checkstyle":
		return formatCheckstyle(failures), nil
	case "sarif":
		return formatSarif(failures, enabledRules, globalSeverity), nil
	default:
		return "", fmt.Errorf("formatting - getting formatter: unknown formatter %s", formatterName)
	}
}

func formatDefault(failures []Failure) string {
	var b strings.Builder
	for _, f := range failures {
		if f.Position.Start.Column == 0 {
			fmt.Fprintf(&b, "%s:%d: %s\n", f.Position.Start.Filename, f.Position.Start.Line, f.Failure)
		} else {
			fmt.Fprintf(&b, "%s:%d:%d: %s\n", f.Position.Start.Filename, f.Position.Start.Line, f.Position.Start.Column, f.Failure)
		}
	}
	return b.String()
}

func formatPlain(failures []Failure) string {
	if len(failures) == 0 {
		return ""
	}
	var b strings.Builder
	for _, f := range failures {
		url := "https://revive.run/r#" + f.RuleName
		if f.Position.Start.Column == 0 {
			fmt.Fprintf(&b, "%s:%d: %s %s\n", f.Position.Start.Filename, f.Position.Start.Line, f.Failure, url)
		} else {
			fmt.Fprintf(&b, "%s:%d:%d: %s %s\n", f.Position.Start.Filename, f.Position.Start.Line, f.Position.Start.Column, f.Failure, url)
		}
	}
	b.WriteString("\n")
	return b.String()
}

func formatUnix(failures []Failure) string {
	if len(failures) == 0 {
		return ""
	}
	var b strings.Builder
	for _, f := range failures {
		if f.Position.Start.Column == 0 {
			fmt.Fprintf(&b, "%s:%d: [%s] %s\n", f.Position.Start.Filename, f.Position.Start.Line, f.RuleName, f.Failure)
		} else {
			fmt.Fprintf(&b, "%s:%d:%d: [%s] %s\n", f.Position.Start.Filename, f.Position.Start.Line, f.Position.Start.Column, f.RuleName, f.Failure)
		}
	}
	b.WriteString("\n")
	return b.String()
}

func formatJSON(failures []Failure) string {
	if failures == nil || len(failures) == 0 {
		return "null\n"
	}
	data, _ := json.Marshal(failures)
	return string(data) + "\n"
}

func formatNDJSON(failures []Failure) string {
	if len(failures) == 0 {
		return ""
	}
	var b strings.Builder
	for _, f := range failures {
		data, _ := json.Marshal(f)
		b.Write(data)
		b.WriteString("\n")
	}
	b.WriteString("\n")
	return b.String()
}

func formatFriendly(failures []Failure) string {
	if len(failures) == 0 {
		return ""
	}
	var b strings.Builder
	const warnSym = "\u26a0" // ⚠
	const errSym = "\u2718"  // ✘
	for _, f := range failures {
		sym := warnSym
		if f.Severity == "error" {
			sym = errSym
		}
		url := "https://revive.run/r#" + f.RuleName
		fmt.Fprintf(&b, "  %s  %s  %s\n", sym, url, f.Failure)
		fmt.Fprintf(&b, "  %s:%d:%d\n\n", f.Position.Start.Filename, f.Position.Start.Line, f.Position.Start.Column)
	}
	errCount := 0
	warnCount := 0
	errRules := map[string]int{}
	warnRules := map[string]int{}
	for _, f := range failures {
		if f.Severity == "error" {
			errCount++
			errRules[f.RuleName]++
		} else {
			warnCount++
			warnRules[f.RuleName]++
		}
	}
	total := len(failures)
	summarySym := warnSym
	if errCount > 0 {
		summarySym = errSym
	}
	probWord := "problems"
	if total == 1 {
		probWord = "problem"
	}
	errWord := "errors"
	if errCount == 1 {
		errWord = "error"
	}
	warnWord := "warnings"
	if warnCount == 1 {
		warnWord = "warning"
	}
	fmt.Fprintf(&b, "%s %d %s (%d %s, %d %s)\n\n", summarySym, total, probWord, errCount, errWord, warnCount, warnWord)
	if errCount > 0 {
		b.WriteString("Errors:\n")
		// sort by count desc, then name asc for determinism
		type kv struct {
			k string
			v int
		}
		var list []kv
		for k, v := range errRules {
			list = append(list, kv{k, v})
		}
		sort.Slice(list, func(i, j int) bool {
			if list[i].v != list[j].v {
				return list[i].v > list[j].v
			}
			return list[i].k < list[j].k
		})
		for _, kv := range list {
			fmt.Fprintf(&b, "  %d  %s\n", kv.v, kv.k)
		}
		b.WriteString("\n")
	}
	if warnCount > 0 {
		b.WriteString("Warnings:\n")
		type kv struct {
			k string
			v int
		}
		var list []kv
		for k, v := range warnRules {
			list = append(list, kv{k, v})
		}
		sort.Slice(list, func(i, j int) bool {
			if list[i].v != list[j].v {
				return list[i].v > list[j].v
			}
			return list[i].k < list[j].k
		})
		for _, kv := range list {
			fmt.Fprintf(&b, "  %d  %s\n", kv.v, kv.k)
		}
		b.WriteString("\n")
	}
	b.WriteString("\n")
	return b.String()
}

func formatStylish(failures []Failure) string {
	if len(failures) == 0 {
		return ""
	}
	// Group by filename, sorted
	byFile := map[string][]Failure{}
	for _, f := range failures {
		fn := f.Position.Start.Filename
		byFile[fn] = append(byFile[fn], f)
	}
	var files []string
	for fn := range byFile {
		files = append(files, fn)
	}
	sort.Strings(files)
	var b strings.Builder
	for _, fn := range files {
		b.WriteString(fn + "\n")
		// Use tabwriter per file
		var buf bytes.Buffer
		w := tabwriter.NewWriter(&buf, 0, 8, 2, ' ', 0)
		// Sort failures in file for determinism? Original is nondeterministic, but we sort by line, col, rule
		list := byFile[fn]
		sort.Slice(list, func(i, j int) bool {
			if list[i].Position.Start.Line != list[j].Position.Start.Line {
				return list[i].Position.Start.Line < list[j].Position.Start.Line
			}
			if list[i].Position.Start.Column != list[j].Position.Start.Column {
				return list[i].Position.Start.Column < list[j].Position.Start.Column
			}
			return list[i].RuleName < list[j].RuleName
