package main

import (
	"fmt"
	"go/build"
	"os"
	"path/filepath"
	"strings"
)

func resolvePatterns(patterns []string, globalExcludes []string) ([]string, error) {
	if len(patterns) == 0 {
		patterns = []string{"."}
	}
	var allFiles []string
	seen := map[string]bool{}
	for _, pat := range patterns {
		files, err := resolveSinglePattern(pat, globalExcludes)
		if err != nil {
			return nil, err
		}
		for _, f := range files {
			if !seen[f] {
				seen[f] = true
				allFiles = append(allFiles, f)
			}
		}
	}
	// Apply global excludes filtering (for files, not for dots? Actually excludes filter after discovery)
	// For dots/dir discovery, files already filtered? No, we need to filter allFiles by excludes.
	var filtered []string
	for _, f := range allFiles {
		if !isExcluded(f, globalExcludes) {
			filtered = append(filtered, f)
		}
	}
	return filtered, nil
}

func resolveSinglePattern(pat string, globalExcludes []string) ([]string, error) {
	// If contains "...", handle as dots pattern (never errors)
	if strings.Contains(pat, "...") {
		return resolveDotsPattern(pat, globalExcludes), nil
	}
	// Check if exists as file or dir
	fi, err := os.Stat(pat)
	if err == nil {
		if fi.IsDir() {
			return resolveDirPattern(pat, globalExcludes), nil
