func parseErrString(s string) (int, int) {
	parts := strings.SplitN(s, ":", 4)
	if len(parts) >= 3 {
		var line, col int
		if parseIntStrict(strings.TrimSpace(parts[1]), &line) && parseIntStrict(strings.TrimSpace(parts[2]), &col) {
			if line > 0 && col > 0 {
				return line, col
			}
		}
		// Try parts[2] may contain "11 "? Already trimmed? For "badparse.go:2:11: expected", parts[2]="11", good.
	}
	return 1, 1
}

func parseIntStrict(s string, out *int) bool {
	s = strings.TrimSpace(s)
	if s == "" {
		return false
	}
	n := 0
	for _, c := range s {
		if c < '0' || c > '9' {
			return false
		}
		n = n*10 + int(c-'0')
	}
	*out = n
	return true
}

