	for i, p := range parts {
		if p == "" {
			continue
		}
		if i == 0 {
			// First part: keep as is? For "Bad" (capital B) => "Bad", for "unexported" (lower) => "unexported". Good: Keep first part as is (preserve case of first letter?).
