func ruleIncrementDecrement(ctx *RuleContext) []Failure {
	var failures []Failure
	f := ctx.File
	// Check for `i += 1` should be `i++`, `i -= 1` should be `i--`? Message: "should replace i += 1 with i++", Category unary-op, Confidence 0.8.
