		assign, ok := n.(*ast.AssignStmt)
		if !ok {
			return true
		}
		// Check Tok is += or -=? assign.Tok is token.ADD_ASSIGN or token.SUB_ASSIGN?
		if assign.Tok != token.ADD_ASSIGN && assign.Tok != token.SUB_ASSIGN {
			return true
		}
		// Must have single LHS and RHS? e.g., `i += 1` has 1 LHS, 1 RHS. What about `a, b += 1, 2`? Unlikely. Check len==1.
		if len(assign.Lhs) != 1 || len(assign.Rhs) != 1 {
