		// RHS must be int literal 1? Check *ast.BasicLit with Kind INT and Value "1"? What about "0x1", "01"? Probably only "1"? Need to probe. For now, check Value=="1".
		rhs, ok := assign.Rhs[0].(*ast.BasicLit)
