		// LHS must be ident? e.g., `i`, `x`, `a[i]`? For `a[i] += 1`, should it suggest `a[i]++`? Possibly yes. Message would be "should replace a[i] += 1 with a[i]++"? Need to probe. For now, handle any LHS, format via go/printer? Or via source slice? Simpler: Get LHS string via content slice from Pos to End? Use fset.Position offsets to slice content? Or use ast printing? We'll use content slice.
		lhsStr := getNodeString(f, assign.Lhs[0])
		var op, replacement string
		if assign.Tok == token.ADD_ASSIGN {
			op = "+="
			replacement = "++"
		} else {
			op = "-="
