func getNodeString(f *LintFile, n ast.Node) string {
	start := f.Fset.Position(n.Pos()).Offset
	end := f.Fset.Position(n.End()).Offset
	if start < 0 || end < 0 || start > len(f.Content) || end > len(f.Content) || start > end {
		return ""
	}
	return string(f.Content[start:end])
}

