	seen := map[string]*fileData{}
	var order []string // to preserve order? Or sort? Original order nondeterministic due to concurrency, but discovery order? For dots, Walk order is lexical? For dir, ReadDir order is sorted? Good: Discovery order deterministic (sorted), but linting concurrency makes output nondeterministic. We'll preserve discovery order, but later sort failures, so order doesn't matter.
	for _, pat := range patterns {
		files, isPackage, err := resolveSinglePatternWithInfo(pat, globalExcludes)
		if err != nil {
			return nil, err
		}
		for _, f := range files {
			if existing, ok := seen[f]; ok {
				// If already seen, update IsFromPackage to true if either is package (package takes precedence for package-comments)
				if isPackage {
					existing.isFromPackage = true
				}
			} else {
				fd := &fileData{name: f, isFromPackage: isPackage}
