func getBasicKind(expr ast.Expr, f *LintFile) (string, bool) {
	// Returns kind string like "untyped string", "string", etc., and whether it's basic (should report).
	switch x := expr.(type) {
	case *ast.BasicLit:
		switch x.Kind {
		case token.STRING:
			return "untyped string", true
		case token.INT:
			return "untyped int", true
		case token.FLOAT:
			return "untyped float", true
		case token.IMAG:
			return "untyped complex", true
		case token.CHAR:
			return "untyped rune", true
		default:
			return "", false
		}
	case *ast.Ident:
		if x.Name == "nil" {
			return "untyped nil", true
		}
		if x.Name == "true" || x.Name == "false" {
			return "untyped bool", true
		}
		if x.Name == "iota" {
			return "untyped int", true
		}
		// For other idents (vars), try to infer type via declaration in file?
		// Look for var declaration with same name in file? e.g., var myKey string => string
		// Search AST for ValueSpec with Names containing x.Name?
		// Also check for := with basic literal? e.g., myKey := "key" => string?
		// For simplicity, if ident and not predeclared, assume it's basic string? No, need to distinguish struct (allowed) vs basic (not allowed).
		// We'll try to find decl: If found and type is basic (string, int, etc.), report as "<kind>" (without untyped). If type is struct or unknown, skip.
		// If not found (e.g., param, imported, etc.), skip? Or assume basic? To avoid false positives, skip (no report) when unknown.
		// Let's implement lookup.
		typ := lookupVarType(f, x.Name)
		if typ == "" {
			return "", false
		}
		// typ is like "string", "int", "bool", etc., or "struct", etc.
		if typ == "string" || typ == "int" || typ == "int8" || typ == "int16" || typ == "int32" || typ == "int64" ||
			typ == "uint" || typ == "uint8" || typ == "uint16" || typ == "uint32" || typ == "uint64" ||
			typ == "float32" || typ == "float64" || typ == "bool" || typ == "byte" || typ == "rune" {
			return typ, true
		}
		// For other types (struct, custom, etc.), skip.
		return "", false
	case *ast.CompositeLit:
		// Struct literal like myKey{}, struct{}{} => allowed, skip.
		return "", false
	default:
		return "", false
	}
}

func lookupVarType(f *LintFile, name string) string {
	// Search for var declaration in file with this name.
	// Check GenDecls (package-level vars) and FuncDecl params? And AssignStmts?
	// For test case: var myKey string (package-level). Good.
	for _, decl := range f.AST.Decls {
		gen, ok := decl.(*ast.GenDecl)
		if !ok || (gen.Tok != token.VAR && gen.Tok != token.CONST) {
			continue
		}
		for _, spec := range gen.Specs {
			vs, ok := spec.(*ast.ValueSpec)
			if !ok {
				continue
			}
			for i, ident := range vs.Names {
				if ident.Name != name {
					continue
				}
				// Found. Determine type: vs.Type may be nil (inferred from Values)? e.g., var myKey = "key" (no explicit type, inferred string). Check Values?
				if vs.Type != nil {
					// vs.Type is Expr, e.g., Ident "string", Selector "pkg.Type", Star, etc.
					if ident, ok := vs.Type.(*ast.Ident); ok {
						return ident.Name
					}
					// For other types (e.g., *T, []T, struct, etc.), return non-basic? Return "" to skip? Or return type string? For simplicity, return "struct" for non-ident (to skip).
					return "struct"
				} else {
					// No explicit type, infer from Values? e.g., var myKey = "key" => string, var x = 1 => int.
					if len(vs.Values) > i {
						// Values may have fewer than Names? For "var a, b = 1, 2", Values len 2, Names len 2, corresponding. For "var a, b int = 1, 2", Type present, already handled. For "var a = 1", Values[0] corresponds to Names[0].
						// For simplicity, if Values len == 1 and Names len >1? e.g., var a, b = foo()? Then unknown. Skip.
						var val ast.Expr
						if len(vs.Values) == len(vs.Names) {
							val = vs.Values[i]
						} else if len(vs.Values) == 1 {
							val = vs.Values[0]
						} else {
							return ""
						}
						if lit, ok := val.(*ast.BasicLit); ok {
							switch lit.Kind {
							case token.STRING:
								return "string"
							case token.INT:
								return "int"
							case token.FLOAT:
								return "float64"
							case token.CHAR:
								return "rune"
							}
						}
						if ident, ok := val.(*ast.Ident); ok {
							if ident.Name == "true" || ident.Name == "false" {
								return "bool"
							}
							if ident.Name == "nil" {
								return "nil"
							}
						}
					}
					return ""
				}
			}
		}
	}
	// Check func params? e.g., func Foo(myKey string)? If key is param name, its type is known from func decl. But our key is ident used in call inside func, which could be param. To find param type, need to know which func contains the call. That's complex (need parent). For simplicity, skip (return ""), so no report for param keys (false negative, but unlikely tested with param keys?).
	return ""
}

