func qualifyType(typeStr, pkgName string) string {
	// typeStr like "*myType", "myType", "[]myType", etc. Need to prefix unexported idents with pkgName + "."?
	// For simplicity, handle Star and Ident only (most common). For "*myType" => "*test.myType", "myType" => "test.myType".
