	}
}

func isBuiltinType(name string) bool {
	switch name {
	case "bool", "byte", "complex64", "complex128", "error", "float32", "float64",
		"int", "int8", "int16", "int32", "int64", "rune", "string",
		"uint", "uint8", "uint16", "uint32", "uint64", "uintptr":
		return true
	default:
		return false
	}
}

func qualifyType(typeStr, pkgName string) string {
	// typeStr like "*myType", "myType", "[]myType", etc. Need to prefix unexported idents with pkgName + "."?
	// For simplicity, handle Star and Ident only (most common). For "*myType" => "*test.myType", "myType" => "test.myType".
	// For "[]myType" => "[]test.myType"? etc. We'll do simple replacement: Find unexported ident and prefix?
	// Simpler: If typeStr starts with "*", then rest = typeStr[1:], qualifiedRest = pkgName + "." + rest (if rest is ident, lowercase, not builtin)? Then "*" + qualifiedRest.
	// If typeStr is ident (no *, [, etc.), then pkgName + "." + typeStr.
	// For other composite, return as is? Or try to qualify? For test case "*myType", handle Star.
	if strings.HasPrefix(typeStr, "*") {
		rest := typeStr[1:]
		// rest could be "myType" (ident) or more complex? For "*myType", rest "myType", qualify.
		if rest != "" && rest[0] >= 'a' && rest[0] <= 'z' && !isBuiltinType(rest) {
			return "*" + pkgName + "." + rest
		}
		return typeStr
	}
	// Check if typeStr is simple ident (no [, ], (, ), space, etc.)?
	if !strings.ContainsAny(typeStr, "[]*(){}, ") && typeStr != "" && typeStr[0] >= 'a' && typeStr[0] <= 'z' && !isBuiltinType(typeStr) {
		return pkgName + "." + typeStr
	}
	return typeStr
}
