			if !xOk || !yOk {
				return true
			}
			var result bool
			switch x.Op {
			case token.EQL:
				result = (xVal == yVal)
			case token.NEQ:
				result = (xVal != yVal)
			case token.LAND:
				result = (xVal && yVal)
			case token.LOR:
				result = (xVal || yVal)
			}
			msg := fmt.Sprintf("expression always evaluates to %v", result)
			// Original message for true: "expression always evaluates to true" (lowercase true/false, via %v? Good: %v for bool gives true/false.)
			failure := newFailure(ctx, "logic", msg, 1, x.Pos(), x.End())
			failure.RuleName = "constant-logical-expr"
			failures = append(failures, failure)
		case *ast.UnaryExpr:
			if x.Op != token.NOT {
				return true
			}
			val, ok := getBoolValue(x.X)
			if !ok {
				return true
			}
			result := !val
			msg := fmt.Sprintf("expression always evaluates to %v", result)
			failure := newFailure(ctx, "logic", msg, 1, x.Pos(), x.End())
			failure.RuleName = "constant-logical-expr"
			failures = append(failures, failure)
		}
		return true
	})
	return failures
}

func getBoolValue(expr ast.Expr) (bool, bool) {
	if ident, ok := expr.(*ast.Ident); ok {
		if ident.Name == "true" {
			return true, true
		}
		if ident.Name == "false" {
			return false, true
		}
	}
	return false, false
}
