func isBoolLiteral(expr ast.Expr) bool {
	if ident, ok := expr.(*ast.Ident); ok {
		return ident.Name == "true" || ident.Name == "false"
	}
	return false
}

func ruleConstantLogical(ctx *RuleContext) []Failure {
	var failures []Failure
	f := ctx.File
	// Check for constant logical exprs that always evaluate to true/false? e.g., `true == true` always true, `true && false` always false, etc.? Message: "expression always evaluates to true" or "... false"? Category logic, Conf 1, Pos at expr (same as bool-literal?).
	// For `true == true`, both bool-literal and constant-logical trigger at same pos (as we saw in bad.go with enableAll: both at 8:5->8:17 for `true == true`). Good: Same pos, different messages/categories.
	// Implement: For BinaryExpr with ==, !=, &&, ||, etc., where both sides are bool literals? Evaluate? e.g., `true == true` => true, `true != false` => true, `true && true` => true, `true || false` => true, etc. Report with message "expression always evaluates to true/false" accordingly.
	// What about `x == true` where x is var (not constant)? Then not constant, no report (only bool-literal reports, not constant-logical). Good: constant-logical only when both sides constant? Or when expr can be evaluated statically? For `true == true`, both sides true/false, constant. For `x == true` (x var), not constant, no report. Good.
	// What about `!true` (unary)? `!true` always false, `!false` always true. Report? Likely yes. Message "expression always evaluates to ..."? Good.
	ast.Inspect(f.AST, func(n ast.Node) bool {
		switch x := n.(type) {
		case *ast.BinaryExpr:
			if x.Op != token.EQL && x.Op != token.NEQ && x.Op != token.LAND && x.Op != token.LOR {
				return true
			}
			// Check if both sides are bool literals? Or more generally, if expr is constant? For simplicity, only when both sides are true/false.
			xVal, xOk := getBoolValue(x.X)
			yVal, yOk := getBoolValue(x.Y)
			if !xOk || !yOk {
				return true
			}
			var result bool
			switch x.Op {
			case token.EQL:
				result = (xVal == yVal)
			case token.NEQ:
				result = (xVal != yVal)
			case token.LAND:
				result = (xVal && yVal)
			case token.LOR:
				result = (xVal || yVal)
			}
			msg := fmt.Sprintf("expression always evaluates to %v", result)
			// Original message for true: "expression always evaluates to true" (lowercase true/false, via %v? Good: %v for bool gives true/false.)
			failure := newFailure(ctx, "logic", msg, 1, x.Pos(), x.End())
			failure.RuleName = "constant-logical-expr"
			failures = append(failures, failure)
		case *ast.UnaryExpr:
			if x.Op != token.NOT {
				return true
			}
			val, ok := getBoolValue(x.X)
			if !ok {
				return true
			}
			result := !val
			msg := fmt.Sprintf("expression always evaluates to %v", result)
			failure := newFailure(ctx, "logic", msg, 1, x.Pos(), x.End())
			failure.RuleName = "constant-logical-expr"
			failures = append(failures, failure)
		}
		return true
	})
	return failures
}

func getBoolValue(expr ast.Expr) (bool, bool) {
	if ident, ok := expr.(*ast.Ident); ok {
		if ident.Name == "true" {
			return true, true
		}
		if ident.Name == "false" {
			return false, true
		}
	}
	return false, false
}
